package openapi

import (
	"strings"
	"testing"
)

func TestRenderGoDocumentUsesRawStringLiteral(t *testing.T) {
	source, err := RenderGoDocument([]byte(`{"openapi":"3.0.3"}`), GoDocumentOptions{
		PackageName:  "docs",
		FunctionName: "ReadDoc",
		ConstName:    "docJSON",
		GeneratedBy:  "test generator",
	})
	if err != nil {
		t.Fatalf("RenderGoDocument() error = %v", err)
	}

	text := string(source)
	for _, want := range []string{
		"// Code generated by test generator; DO NOT EDIT.",
		"package docs",
		"func ReadDoc() []byte",
		"const docJSON = `{\"openapi\":\"3.0.3\"}`",
	} {
		if !strings.Contains(text, want) {
			t.Fatalf("source missing %q:\n%s", want, text)
		}
	}
}

func TestRenderGoDocumentFallsBackToQuotedString(t *testing.T) {
	source, err := RenderGoDocument([]byte("{\"description\":\"value with ` backtick\"}"), GoDocumentOptions{PackageName: "docs"})
	if err != nil {
		t.Fatalf("RenderGoDocument() error = %v", err)
	}

	text := string(source)
	if strings.Contains(text, "const openAPIDocument = `") {
		t.Fatalf("source used raw string literal for backtick data:\n%s", text)
	}
	if !strings.Contains(text, "const openAPIDocument = \"") || !strings.Contains(text, "value with ` backtick") {
		t.Fatalf("source missing quoted string fallback:\n%s", text)
	}
}

func TestRenderGoDocumentRequiresPackageName(t *testing.T) {
	_, err := RenderGoDocument([]byte("{}"), GoDocumentOptions{})
	if err == nil {
		t.Fatal("RenderGoDocument() error = nil, want package name error")
	}
	if !strings.Contains(err.Error(), "package name is required") {
		t.Fatalf("error = %q, want package name is required", err)
	}
}
